import React, { HTMLAttributes } from 'react';

import clsx from 'clsx';
import { Link } from 'react-router-dom';

import { getUrlFromObstacleType } from '@apps/Obstacles/@mappers/obstacles.url.mapper';
import { getObstacleTypeName } from '@apps/Obstacles/@resources/obstacles.resource';

import { IBaseObstacle, ObstacleCategory } from '../../@types/obstacles.types';
import ObstacleCategoryBadge from '../ObstacleCategoryBadge/ObstacleCategoryBadge';
import { ObstacleIcon } from '../ObstacleIcon/ObstacleIcon';
interface IObstacleBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  obstacle: IBaseObstacle;
  link?: boolean;
}

export const ObstacleBadge: React.FC<IObstacleBadgeProps> = ({ obstacle, link, ...rest }) => {
  const comp = (
    <span
      className={clsx('d-flex horizontal-gapped align-items-center')}
      title={getObstacleTypeName(obstacle.type)}
    >
      <ObstacleIcon type={obstacle.type} />
      <strong>{obstacle.name}</strong>
      {obstacle.category != ObstacleCategory.CategoryNo && (
        <ObstacleCategoryBadge category={obstacle.category} />
      )}
    </span>
  );
  if (link) {
    return (
      <Link {...rest} to={`/obstacles/${getUrlFromObstacleType(obstacle.type)}/${obstacle.id}`}>
        {comp}
      </Link>
    );
  }
  return <span {...rest}>{comp}</span>;
};
